'use strict';
/* FRYE CORSA: motorsport-inspired presentation, without third-party branding. */
document.body.classList.add('corsa-theme');
const liveTelemetry={};
const raceMetrics=()=>{
 const committed=state.positions.reduce((a,p)=>a+p.entry*p.qty,0)+state.orders.reduce((a,p)=>a+p.limit*p.qty,0);
 const load=equity()>0?committed/equity()*100:0;
 const signal=signalFixtures.find(s=>s.symbol===symbol)||signalFixtures[0];
 return [
 {id:'drive',name:'Market drive',code:'MKT',value:liveTelemetry.score ?? 76,max:100,unit:'ALIGNMENT / 100',status:'CONSTRUCTIVE',detail:'The overview’s hypothetical regime alignment score. This is a presentation fixture, not an engine calculation.',source:'Market context fixture',destination:'xray'},
 {id:'breadth',name:'Participation',code:'BRD',value:liveTelemetry.breadth ?? 68.4,max:100,unit:'ADVANCING / %',status:'BROADENING',detail:'Illustrative share of advancing constituents in the mock universe. It matches the Market X-Ray breadth fixture.',source:'Breadth fixture',destination:'xray'},
 {id:'volatility',name:'Volatility',code:'VOL',value:18.42,max:40,unit:'INDEX / 0–40',status:'MODERATE',detail:'The fictional volatility index shown in Market X-Ray. Gauge range is a display choice, not a predictive risk model.',source:'Volatility context fixture',destination:'xray'},
 {id:'capital',name:'Capital load',code:'CAP',value:load,max:100,unit:'COMMITTED / %',status:load>80?'HIGH LOAD':load>0?'CAPITAL ENGAGED':'UNCOMMITTED',detail:'Open-position entry notional plus pending-order limit notional, divided by current paper equity. This shows capital commitment, not maximum loss or stop-based risk.',source:'Local simulated paper ledger',destination:'paper'},
 {id:'trend',name:'Trend alignment',code:'TRD',value:75,max:100,unit:'3 OF 4 / TIMEFRAMES',status:'TREND SUPPORT',detail:'Three of four timeframes are bullish in the existing X-Ray fixture; one is consolidating. No live trend engine is connected.',source:'Multi-timeframe fixture',destination:'xray'},
 {id:'conviction',name:'Setup conviction',code:'SET',value:signal.confidence,max:100,unit:`${symbol} / FIXTURE SCORE`,status:signal.status.toUpperCase(),detail:`${symbol} uses the ${signal.strategy} example. This is the illustrative confidence label from the signal fixture, not a calibrated probability of profit.`,source:'Signal qualification fixture',destination:'signals'}
 ];
};
const raceValue=m=>m.id==='volatility'?m.value.toFixed(2):m.id==='breadth'||m.id==='capital'?m.value.toFixed(1):String(Math.round(m.value));
let raceGaugeSequence=0;
function raceGauge(metric,mini=false){const gaugeId='race-dial-'+(++raceGaugeSequence),p=Math.max(0,Math.min(1,metric.value/metric.max)),point=(r,a)=>[100+r*Math.cos(a*Math.PI/180),95+r*Math.sin(a*Math.PI/180)],arc=(a,b,r=70)=>{const s=point(r,a),e=point(r,b);return `M${s.join(',')} A${r},${r} 0 ${b-a>180?1:0} 1 ${e.join(',')}`},angle=150+p*240;return `<svg class="race-dial" viewBox="0 0 200 172" role="img" aria-label="${metric.name}: ${raceValue(metric)} ${metric.unit}"><defs><linearGradient id="${gaugeId}"><stop stop-color="#f02a3f"/><stop offset=".7" stop-color="#f02a3f"/><stop offset="1" stop-color="#ffdc35"/></linearGradient></defs><path d="${arc(150,390)}" stroke="#272d33" stroke-width="8" fill="none"/><path class="race-dial-progress" d="${arc(150,390)}" pathLength="100" stroke="url(#${gaugeId})" stroke-width="8" stroke-dasharray="${p*100} 100" fill="none" style="--dial-fill:${p*100}"/>${Array.from({length:25},(_,i)=>{const a=150+i*10,s=point(i%4===0?55:59,a),e=point(64,a);return `<line x1="${s[0]}" y1="${s[1]}" x2="${e[0]}" y2="${e[1]}" stroke="${i>=21?'#dfbc36':i%4===0?'#9ba0a4':'#41494f'}" stroke-width="${i%4===0?'1.5':'1'}"/>`}).join('')}<text x="100" y="28" class="race-dial-code">${metric.code}</text><text x="35" y="139" class="race-dial-scale">0</text><text x="165" y="139" text-anchor="end" class="race-dial-scale">${metric.max}</text><g class="race-needle" style="--needle-angle:${angle}deg"><path d="M92 92 L157 95 L92 98 Z" fill="#ffdd37"/><path d="M86 93 L100 95 L86 97 Z" fill="#e52d40"/></g><circle cx="100" cy="95" r="8" fill="#101318" stroke="#454749" stroke-width="2"/><circle cx="100" cy="95" r="2" fill="#ef3347"/><text x="100" y="144" class="race-dial-value">${raceValue(metric)}</text><text x="100" y="159" class="race-dial-unit">${esc(metric.unit)}</text></svg>`}
function raceMeter(m,i,mini=false){return `<button class="race-meter ${mini?'race-meter-mini':''}" data-action="race-meter:${m.id}"><div class="race-meter-title"><span>${m.name}</span><small>${String(i+1).padStart(2,'0')}</small></div>${raceGauge(m,mini)}<div class="race-meter-status"><i></i>${m.status}</div>${mini?'':`<span class="race-meter-origin">${m.id==='capital'?'PAPER LEDGER':'DEMO FIXTURE'} ${icon('arrow',11)}</span>`}</button>`}
function raceHero(compact=false){return `<section class="race-hero ${compact?'race-hero-compact':''}"><div class="race-hero-content"><div class="race-kicker"><span></span>REDLINE <i>/</i> PERFORMANCE TRADING</div><h1>PRECISION<span>IN EVERY MOVE.</span></h1><p>The trading cockpit. Structure, momentum and capital under control.</p><div class="head-actions">${btn('Open chart cockpit','workspace',true,'chart')}${btn('Presentation lap','tour',false,'play')}</div></div><div class="race-hero-visual" aria-hidden="true"><span class="race-hero-word">CORSA</span><svg viewBox="0 0 450 200"><path d="M116 42 H298 C328 42 321 86 352 86 H368 C410 86 414 154 369 154 H224 C188 154 178 103 144 103 C110 103 108 157 71 157 C31 157 40 119 55 90 L71 59 Q80 42 116 42 Z" fill="none" stroke="#343a40" stroke-width="19"/><path d="M116 42 H298 C328 42 321 86 352 86 H368 C410 86 414 154 369 154 H224 C188 154 178 103 144 103 C110 103 108 157 71 157 C31 157 40 119 55 90 L71 59 Q80 42 116 42 Z" fill="none" stroke="#979c9d" stroke-width="1" stroke-dasharray="2 7" opacity=".65"/><path d="M116 42H241" stroke="#f02b3f" stroke-width="7"/><path d="M245 42H298" stroke="#ffd52d" stroke-width="7"/><circle class="race-start-beacon" cx="241" cy="42" r="6" fill="#ffd52d" stroke="#121212" stroke-width="3"/><g class="race-moving-car"><ellipse cx="-1" cy="1" rx="12" ry="6" fill="#000" opacity=".45"/><rect x="-7" y="-6" width="5" height="3" rx="1" fill="#080808" stroke="#666" stroke-width=".5"/><rect x="-7" y="3" width="5" height="3" rx="1" fill="#080808" stroke="#666" stroke-width=".5"/><rect x="5" y="-6" width="4" height="3" rx="1" fill="#080808" stroke="#666" stroke-width=".5"/><rect x="5" y="3" width="4" height="3" rx="1" fill="#080808" stroke="#666" stroke-width=".5"/><path d="M-9-3 L-3-4 L3-2.5 L10-1.3 L10 1.3 L3 2.5 L-3 4 L-9 3Z" fill="#ff142b" stroke="#ff6472" stroke-width=".6"/><rect x="-10" y="-5" width="2" height="10" rx=".6" fill="#ed0018"/><rect x="8" y="-5" width="2" height="10" rx=".6" fill="#ff2437"/><ellipse cx="0" cy="0" rx="2.8" ry="1.7" fill="#101010"/><circle cx="0" cy="0" r="1.2" fill="#ffdc00"/><path d="M3 0H8" stroke="#fff" stroke-width=".7"/><animateMotion dur="8s" repeatCount="indefinite" calcMode="paced" rotate="auto" path="M116 42 H298 C328 42 321 86 352 86 H368 C410 86 414 154 369 154 H224 C188 154 178 103 144 103 C110 103 108 157 71 157 C31 157 40 119 55 90 L71 59 Q80 42 116 42 Z"/></g></svg><div class="race-hero-session"><strong>019<span>/ DEMO SESSION</span></strong><span>US EQUITIES <i>·</i> SIMULATED TELEMETRY</span><em class="backend-connection-status" data-backend-status>API CHECKING</em></div></div></section>`}
const beforeRaceOverview=overview;
overview=function(){let content=beforeRaceOverview(),start=content.indexOf('<div class="stats">');if(start>=0)content=content.slice(start);return raceHero()+`<section class="live-snapshot-panel" data-live-snapshot><div><span class="eyebrow">LIVE BACKEND SNAPSHOT</span><strong data-live-state>Loading ES data…</strong><small data-live-meta>Reading canonical client API</small></div><div class="live-snapshot-values"><span><b data-live-score>—</b><small>10m score</small></span><span><b data-live-market>—</b><small>market state</small></span><span><b data-live-sectors>—</b><small>sector cards</small></span></div></section>`+`<div class="race-section-label"><span>SESSION TELEMETRY</span><small>ILLUSTRATIVE MARKET READS / PAPER CAPITAL</small><a href="#/meters">Full instrument cluster ${icon('arrow',12)}</a></div><div class="race-meter-grid">${raceMetrics().slice(0,4).map((m,i)=>raceMeter(m,i)).join('')}</div>`+content;};
function raceMetersPage(){return head('PERFORMANCE METERS','A cockpit view of market context, setup alignment and simulated capital.',btn('Open chart cockpit','workspace',true,'chart'),'REDLINE / INSTRUMENT CLUSTER')+`<div class="race-cluster-banner"><span class="race-cluster-stripes"></span><strong>READ THE CONDITIONS.<span>KEEP THE CONTROL.</span></strong><div><span>SELECTED MARKET</span><select id="raceSymbol" aria-label="Meter symbol">${symbols.map(s=>`<option ${symbol===s[0]?'selected':''}>${s[0]}</option>`).join('')}</select></div><span class="pill gold">SIMULATED TELEMETRY</span></div><div class="race-full-cluster">${raceMetrics().map((m,i)=>raceMeter(m,i)).join('')}</div><div class="notice">Market, breadth, volatility, trend and conviction dials use clearly labeled presentation fixtures. Capital load is calculated from your local paper ledger. Gauge positions do not grant trade permission or change the client’s engine boundaries.</div><div class="grid cols-2">${panel('CAPITAL / CONTROL',`<div class="panel-body"><div class="kv"><span>Paper equity</span><strong class="number">${money(equity())}</strong></div><div class="kv"><span>Available buying power</span><strong class="number">${money(available())}</strong></div><div class="kv"><span>Open positions / pending orders</span><strong>${state.positions.length} / ${state.orders.length}</strong></div>${btn('Open paper desk','paper',false,'wallet')}</div>`)}${panel('STRUCTURE / AUTHORITY',`<div class="panel-body"><p class="metric-description">Engine 22 owns structure. Engine 27 interprets it. Engine 26 proposes location and geometry. Engine 6 remains the final permission boundary.</p>${btn('Inspect engine boundaries','engines',false,'shield')}</div>`)}</div>`}
nav.splice(nav.findIndex(n=>n[0]==='xray')+1,0,['meters','Performance Meters','target']);
window.fryePages={...window.fryePages,meters:raceMetersPage};
const beforeRaceAction=action;
action=function(value){if(value==='meters'){closeModal();go('meters');return}if(value.startsWith('race-meter:')){const m=raceMetrics().find(m=>m.id===value.split(':')[1]);if(!m)return;openModal(`${m.name} / Telemetry read`,`${raceGauge(m)}<div class="race-meter-detail-value"><span>${m.status}</span><strong>${raceValue(m)} <small>${esc(m.unit)}</small></strong></div><p class="metric-description">${m.detail}</p><div class="kv"><span>Source</span><strong>${m.source}</strong></div><div class="kv"><span>Gauge display range</span><strong>0–${m.max}</strong></div>`,btn(m.destination==='paper'?'Open paper desk':m.destination==='signals'?'Open signal center':'Open Market X-Ray',m.destination,true,'arrow'));return}beforeRaceAction(value)};
const beforeRaceBind=bindPage;
bindPage=function(){beforeRaceBind();document.body.classList.toggle('race-dashboard',page==='overview');const brand=$('.terminal-brand-copy>small');if(brand)brand.textContent='PERFORMANCE TRADING';const status=$('.terminal-status-brand');if(status)status.innerHTML='REDLINE<span>PRO</span>';const meterSelect=$('#raceSymbol');if(meterSelect)meterSelect.onchange=e=>{symbol=e.target.value;render()};if(page==='chart'&&chartTab==='watchlist'){const watch=$('.terminal-watch-table');if(watch){const metrics=raceMetrics();watch.insertAdjacentHTML('afterend',`<section class="race-chart-telemetry"><div class="race-chart-telemetry-title"><strong>COCKPIT TELEMETRY</strong><a href="#/meters" title="Open performance meters" aria-label="Open performance meters">${icon('expand',12)}</a></div><div>${raceMeter(metrics[0],0,true)}${raceMeter(metrics[3],3,true)}</div></section>`);bindActions($('.race-chart-telemetry'));}}};
route();








